def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    max_unique_count = 0
    result = ""
    for word in words:
        count = unique_char_count(word)
        if count > max_unique_count or (count == max_unique_count and word < result):
            max_unique_count = count
            result = word
    return result

